async function initialize() {
  try {
    const [catalogResponse, previewsResponse] = await Promise.all([Promise.resolve({ok:true,json:async()=>embeddedCatalog}), Promise.resolve({ok:true,json:async()=>embeddedManifest})]);
    if (!catalogResponse.ok || !previewsResponse.ok) throw new Error('衣橱未准备好');
    const catalog = await catalogResponse.json(); manifest = await previewsResponse.json();
    store = createOutfitStore(catalog, {topId:'top-1',bottomId:'bottom-3'});
    for(const top of store.tops) for(const bottom of store.bottoms) if(!manifest[`${top.id}__${bottom.id}`]) throw new Error('组合预览不完整');
    busy = true;
    $('preview').classList.add('preparing');
    let completed = 0;
    const sources = [...new Set([...catalog.map(item => item.source), ...Object.values(manifest)])];
    let cursor = 0;
    await Promise.all(Array.from({length: 4}, async () => {
      while (cursor < sources.length) {
        const src = sources[cursor++];
        ready.set(src, await loadImage(src));
        completed++;
        $('preview-loading').textContent = `正在准备实时穿搭 ${Math.round(completed / sources.length * 100)}%`;
      }
    }));
    store.subscribe(renderOutfit); renderOutfit(store.current);
    setupCloset();
    busy = false; $('spin').disabled = false; $('custom-open').disabled = false;
    $('preview').classList.remove('preparing');
    $('status').textContent = '万Wool皆可时髦'; $('button-label').textContent = '随机搭配';
  } catch(error) {
    store = null; $('status').textContent = '衣橱暂未准备好'; $('error').hidden = false;
    $('error').textContent = '穿搭素材未能加载，请点击按钮重试。';
    $('button-label').textContent = '重新加载'; $('spin').disabled = false;
    console.error(error);
  }
}
